from pathlib import Path
import json,hashlib,time,math
import numpy as np
import pyvista as pv
ROOT=Path('/repo');OUT=Path('/out');sha=lambda p:hashlib.sha256(Path(p).read_bytes()).hexdigest();plan=json.loads((OUT/'plan.json').read_text());step=ROOT/plan['source_STEP_path'];stl=ROOT/plan['display_STL_path'];assert sha(step)==plan['source_STEP_sha256'] and sha(stl)==plan['display_STL_sha256'];mesh=pv.read(str(stl));assert mesh.n_cells==384;mesh.cell_data['display_source_triangle']=np.arange(mesh.n_cells);points=mesh.points.copy();faces=mesh.faces.copy();c=np.array(mesh.center);media=OUT/'media';frames=OUT/'frames';media.mkdir(mode=0o700);frames.mkdir(mode=0o700);records={};start=time.monotonic()
p=pv.Plotter(off_screen=True,window_size=(1600,1100),shape=(3,1),row_weights=[.18,.68,.14],border=False);p.set_background('#edf1f4');p.subplot(1,0);p.add_mesh(mesh,color='#718b99',opacity=1,smooth_shading=False,split_sharp_edges=False,show_edges=False,ambient=.3,diffuse=.7,specular=0);p.add_axes(interactive=False);p.enable_parallel_projection();p.subplot(0,0);p.add_text('ASSUMED CENTRAL CELL | EDITABLE GEOMETRY STUDY',position=(.01,.78),viewport=True,font_size=13,color='#172535');p.add_text('Open-top tub, tunnel, closed sills, bulkheads and seat crossmembers\nLiteral 3 mm plate volumes; dimensions are hypotheses, not measured Porsche interfaces',position=(.01,.34),viewport=True,font_size=11,color='#172535');p.subplot(2,0);p.add_text('Authored STEP tessellation, all 384 display triangles retained; no hidden surfaces added\nCPU VTK view, not Omniverse; appearance does not establish strength, fit, manufacturing or road/track approval',position=(.01,.35),viewport=True,font_size=10,color='#172535');p.subplot(1,0)
def capture(path,eye,up,scale):
 p.camera_position=[eye.tolist(),c.tolist(),up];p.camera.parallel_scale=scale;p.reset_camera_clipping_range();p.render();p.screenshot(path);return {'camera':[list(x) for x in p.camera_position],'parallel_scale_display_units':p.camera.parallel_scale,'parallel_projection':bool(p.camera.parallel_projection),'image_sha256':sha(path)}
for name,offset,up,scale in [('isometric',[2500,-2700,2000],[0,0,1],1250),('top',[0,0,4000],[1,0,0],1200),('side',[0,-4000,0],[0,0,1],700),('longitudinal_end',[-4000,0,0],[0,0,1],700)]:
 path=media/(name+'.png');records[name]={'path':str(path.relative_to(OUT)),**capture(path,c+offset,up,scale)}
frame_records=[]
for i in range(120):
 angle=math.radians(-45+3*i);path=frames/f'frame-{i:04d}.png';frame_records.append({'index':i,'time_seconds':i/24,'azimuth_degrees':-45+3*i,**capture(path,c+np.array([3200*math.cos(angle),3200*math.sin(angle),2100]),[0,0,1],1300)})
capabilities=p.ren_win.ReportCapabilities();assert 'llvmpipe' in capabilities.lower();(OUT/'render-capabilities.txt').write_text(capabilities);p.close();assert np.array_equal(mesh.points,points) and np.array_equal(mesh.faces,faces);assert sha(step)==plan['source_STEP_sha256'] and sha(stl)==plan['display_STL_sha256'];r={'classification':plan['classification'],'plan_sha256':sha(OUT/'plan.json'),'script_sha256':sha(__file__),'source_STEP_sha256':sha(step),'display_STL_sha256':sha(stl),'stills':records,'orbit_frames':frame_records,'frame_count':120,'fps':24,'geometry_display_unchanged':True,'complete_display_triangles_retained':384,'native_omniverse':False,'runtime':'CPU VTK EGL / Mesa llvmpipe','elapsed_seconds':time.monotonic()-start};(OUT/'result.json').write_text(json.dumps(r,indent=2)+'\n');print(json.dumps({'stills':len(records),'frames':120,'seconds':r['elapsed_seconds']}))
